head.script:
scwin.trigger1_onclick = function(e) {
	dataList1.setData(["A", 110, 120, 130, 140, "B", 210, 220, 230, 240, "C", 310, 320, 330, 340, "D", 410, 420, 430, 440]);
};
scwin.trigger3_onclick = function(e) {
	var options = {};
	options.fileName = "line.xlsx";
	options.type = "1";
	options.showProcess = false;
	options.chart = {
		"chartName": "line",
		"chartType": "",
		"title": "차트 타이틀",
		"yTitle": "Y 타이틀",
		"xTitle": "X 타이틀",
		"startRowIndex": 0,
		"startColIndex": 5,
		"endRowIndex": 20,
		"endColIndex": 15,
		"serAxis": "true",
		"catAxis": "true",
		"catAxisRange": {
			"startColIndex": 1,
			"startRowIndex": 0,
			"endColIndex": 4,
			"endRowInex": 0
		},
		"serAxisRange": {
			"startColIndex": 0,
			"startRowIndex": 1,
			"endColIndex": 0,
			"endRowIndex": 4
		},
		"dataAxisRange": {
			"startColIndex": 1,
			"startRowIndex": 1,
			"endColIndex": 4,
			"endRowIndex": 4
		},
		"catGridLines": "true", // 가로
		"serGridLines": "true", // 세로
		"legend": "true", // 범례
		"legendPosition": "bottom" // 범례위치
	};
	var infoArr = [];
	gridView1.advancedExcelDownload(options, infoArr);
};
